edits.after:
root = kernfs_root(kn);
down_read(&root->kernfs_rwsem);

do {
	struct dentry *dtmp;
	struct kernfs_node *kntmp;
	const char *name;
	char *s;

	knparent = kernfs_dentry_node(dentry);
	if (kn == knparent) {
		up_read(&root->kernfs_rwsem);
		return dentry;
	}
	kntmp = find_next_ancestor(kn, knparent);
	if (WARN_ON(!kntmp)) {
		up_read(&root->kernfs_rwsem);
		dput(dentry);
		return ERR_PTR(-EINVAL);
	}
	name = rcu_dereference_check(kntmp->name, lockdep_is_held(&root->kernfs_rwsem));
	s = kstrdup(name, GFP_KERNEL);
	if (!s) {
		up_read(&root->kernfs_rwsem);
		dput(dentry);
		return ERR_PTR(-ENOMEM);
	}
	up_read(&root->kernfs_rwsem);
	dtmp = lookup_positive_unlocked(s, dentry, strlen(s));
	kfree(s);
	dput(dentry);
	if (IS_ERR(dtmp))
		return dtmp;
	dentry = dtmp;
	down_read(&root->kernfs_rwsem);
} while (true);

